failure.message:
AssertionError: expected 400 after PUT with ISO-Z expiresAt, got 500: {"message":"Internal server error"}
assert 500 == 400
 +  where 500 = <Response [500]>.status_code

AssertionError: expected 400 after PUT with ISO (no Z) expiresAt, got 500: {"message":"Internal server error"}
assert 500 == 400
 +  where 500 = <Response [500]>.status_code

AssertionError: Expected upper-cased validation to succeed, got 404: {"detail":"Invalid discount code"}
assert 404 == 200
 +  where 404 = <Response [404]>.status_code
